<?php
require_once __DIR__.'/_layout.php';$customers=$pdo->query("SELECT u.*,COUNT(b.booking_id) booking_count FROM users u LEFT JOIN bookings b ON b.user_id=u.user_id WHERE u.role='customer' GROUP BY u.user_id ORDER BY u.created_at DESC")->fetchAll();$selected=null;$history=[];if(isset($_GET['id'])){$s=$pdo->prepare('SELECT * FROM users WHERE user_id=? AND role="customer"');$s->execute([(int)$_GET['id']]);$selected=$s->fetch();if($selected){$s=$pdo->prepare('SELECT b.*,r.room_name FROM bookings b JOIN rooms r ON r.room_id=b.room_id WHERE b.user_id=? ORDER BY b.created_at DESC');$s->execute([$selected['user_id']]);$history=$s->fetchAll();}}admin_start('Guest book');?><table class="data-table"><thead><tr><th>Guest</th><th>Email</th><th>Phone</th><th>Joined</th><th>Stays</th><th></th></tr></thead><tbody><?php foreach($customers as $c): ?><tr><td><?= e($c['name']) ?></td><td><?= e($c['email']) ?></td><td><?= e($c['phone']) ?></td><td><?= e($c['created_at']) ?></td><td><?= (int)$c['booking_count'] ?></td><td><a href="?id=<?= (int)$c['user_id'] ?>">History</a></td></tr><?php endforeach; ?></tbody></table><?php if($selected): ?><h2 style="font:25px var(--serif);color:var(--navy);margin-top:36px">Stays for <?= e($selected['name']) ?></h2><table class="data-table"><thead><tr><th>Reference</th><th>Room</th><th>Dates</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($history as $b): ?><tr><td><?= e($b['booking_reference']) ?></td><td><?= e($b['room_name']) ?></td><td><?= e($b['check_in']) ?> — <?= e($b['check_out']) ?></td><td>₹<?= number_format((float)$b['total_amount']) ?></td><td><?= e($b['status']) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><?php admin_end(); ?>
